pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(1000000, "Test", "TST"); }
    function testFuzz_property(uint256 amount, address caller) public {
        vm.assume(caller != address(0));
        amount = bound(amount, 1, c.balanceOf(c.owner()));
        vm.deal(c.owner(), 0);
        vm.prank(c.owner());
        c.transfer(caller, amount);
        uint256 supplyBefore = c.totalSupply();
        vm.prank(caller);
        bool success = false;
        try c.burn(amount) { success = true; } catch { success = false; }
        assertTrue(success ? c.totalSupply() == supplyBefore : c.totalSupply() == supplyBefore);
    }
}
